    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int h, w, q, r, c;
    cin >> h >> w >> q >> r >> c;
    Paint st(h, w, r * w + c);
    while (q--) {
        cin >> r >> c;
        cout << st.add(r * w + c) << '\n';
    }
}

